type Exec = { code: number | null; stdout: string; stderr: string };

function sh(conn: Client, cmd: string): Promise<Exec> {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (err, stream) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      let code: number | null = null;
      stream
        .on("close", (c: number) => resolve({ code: c ?? code, stdout, stderr }))
        .on("exit", (c: number) => (code = c))
        .on("data", (d: Buffer) => (stdout += d.toString()))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString()));
    });
  });
}

async function run(conn: Client, label: string, cmd: string): Promise<Exec> {
  const r = await sh(conn, cmd);
