  if (s!.ipAddress !== "51.79.226.215") throw new Error("IP mismatch");
  const password = decryptSecret(s!.rootPasswordEnc)!;
  const conn = new Client();
  await new Promise<void>((res, rej) =>
    conn.on("ready", res).on("error", rej)
      .connect({ host: "51.79.226.215", port: s!.sshPort ?? 22, username: "root", password, readyTimeout: 30000 }));
  const cmd =
    `cd /opt/nexis && ` +
    `echo '== HEAD =='; git rev-parse --abbrev-ref HEAD; git rev-parse HEAD; ` +
    `echo '== box-baseline vs main =='; echo "box-baseline=$(git rev-parse box-baseline)"; echo "origin/main=$(git rev-parse origin/main)"; ` +
    `echo '== worktree diff vs origin/main (should be empty) =='; git diff --stat origin/main | tail -5; ` +
    `echo '== porcelain status (untracked/modified, non-ignored) =='; git status --porcelain | head -40; echo "porcelain-lines=$(git status --porcelain | wc -l)"; ` +
    `echo '== tracked file count =='; git ls-files | wc -l`;
  await new Promise<void>((res) => {
    conn.exec(cmd, (e, stream) => {
      if (e) throw e;
      stream.on("close", () => { conn.end(); res(); })
        .on("data", (d: Buffer) => process.stdout.write(d.toString()))
        .stderr.on("data", (d: Buffer) => process.stdout.write("ERR:" + d.toString()));
    });
  });
}
main().catch((e) => { console.error(e); process.exit(1); });
